UPDATE sys_menu
SET deleted = 1,
    update_time = NOW()
WHERE deleted = 0
  AND (
    id = #{menuId}
    OR parent_id IN (
        SELECT id FROM (
            SELECT id FROM sys_menu
            WHERE deleted = 0
              AND (
                id = #{menuId}
                OR FIND_IN_SET(#{menuId}, parent_id)
            )
        ) AS temp
    )
)
